import java.util.*;import java.util.zip.*;import java.io.*;import net.minecraft.util.ResourceLocation;import net.minecraft.client.resources.*;import net.minecraft.client.resources.data.IMetadataSection;import software.bernie.geckolib3.file.*;import software.bernie.shadowed.eliotlash.molang.MolangParser;
public class GeckoLoadTest {
 public static void main(String[] args)throws Exception{final ZipFile z=new ZipFile(args[0]);IResourceManager rm=new IResourceManager(){public Set<String> getResourceDomains(){return Collections.singleton("sonicraft");}public List<IResource> getAllResources(ResourceLocation r)throws IOException{return Collections.singletonList(getResource(r));}public IResource getResource(final ResourceLocation r)throws IOException{final String path="assets/"+r.getResourceDomain()+"/"+r.getResourcePath();if(z.getEntry(path)==null)throw new FileNotFoundException(path);return new IResource(){public ResourceLocation getResourceLocation(){return r;}public InputStream getInputStream(){try{return z.getInputStream(z.getEntry(path));}catch(IOException e){throw new RuntimeException(e);}}public boolean hasMetadata(){return false;}public <T extends IMetadataSection>T getMetadata(String s){return null;}public String getResourcePackName(){return "test";}public void close(){}};}};
 int animations=0,models=0;List<String> failed=new ArrayList<>();for(Enumeration<? extends ZipEntry> en=z.entries();en.hasMoreElements();){String n=en.nextElement().getName();try{if(n.startsWith("assets/sonicraft/animations/")&&n.endsWith(".json")){if(new AnimationFileLoader().loadAllAnimations(new MolangParser(),new ResourceLocation("sonicraft",n.substring(17)),rm)==null)throw new AssertionError("null animations");animations++;}if(n.startsWith("assets/sonicraft/geo/")&&n.endsWith(".json")){if(new GeoModelLoader().loadModel(rm,new ResourceLocation("sonicraft",n.substring(17)))==null)throw new AssertionError("null model");models++;}}catch(Throwable e){failed.add(n+": "+e);}}
 z.close();if(!failed.isEmpty()){for(String f:failed)System.err.println(f);throw new AssertionError(failed.size()+" failures");}System.out.println("PASS real GeckoLib loaders: "+models+" geometry files, "+animations+" animation files");}
}
